// Package e2e drives the real unic and unicd binaries: several daemons on one
// machine, each with its own state directory and a directory-backed clipboard
// (UNIC_MOCK_CLIPBOARD_DIR), controlled only through the unic CLI and the clipboard
// directories. Cases are testscript files in testdata/; CASES.md lists them
// (generated by TestCatalog, never edit it by hand). See README.md.
package e2e

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"fmt"
	"hash/crc32"
	"math/rand"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"

	"github.com/rogpeppe/go-internal/testscript"
)

var binDir string

func TestMain(m *testing.M) {
	os.Exit(run(m))
}

func run(m *testing.M) int {
	if os.Getenv("UNIC_E2E") == "" {
		return m.Run() // only the catalog check runs; the cases skip themselves
	}
	if binDir = os.Getenv("UNIC_E2E_BIN"); binDir == "" {
		dir, err := os.MkdirTemp("", "unic-e2e-bin")
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		defer func() { _ = os.RemoveAll(dir) }()
		root, err := repoRoot()
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		for _, name := range []string{"unic", "unicd"} {
			cmd := exec.Command("go", "build", "-tags", "unic_e2e", "-o", filepath.Join(dir, name), "./app/desktop/cmd/"+name)
			cmd.Dir, cmd.Stdout, cmd.Stderr = root, os.Stderr, os.Stderr
			if err := cmd.Run(); err != nil {
				fmt.Fprintln(os.Stderr, "build", name+":", err)
				return 1
			}
		}
		binDir = dir
	}
	return m.Run()
}

func repoRoot() (string, error) {
	out, err := exec.Command("go", "env", "GOMOD").Output()
	if err != nil {
		return "", err
	}
	return filepath.Dir(strings.TrimSpace(string(out))), nil
}

func TestCLI(t *testing.T) {
	if os.Getenv("UNIC_E2E") == "" {
		t.Skip("set UNIC_E2E=1 to run the end-to-end cases (see e2e/cli/README.md)")
	}
	testscript.Run(t, testscript.Params{
		Dir:         "testdata",
		Setup:       setup,
		Cmds:        commands(),
		WorkdirRoot: shortTemp(t),
	})
}

// shortTemp keeps socket paths under the unix limit.
func shortTemp(t *testing.T) string {
	d, err := os.MkdirTemp("/tmp", "ue")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(d) })
	return d
}

// state is one script's daemons.
type state struct {
	mu    sync.Mutex
	work  string
	nodes map[string]*node
}

type node struct {
	name string
	home string
	sock string
	cmd  *exec.Cmd
	done chan struct{}
}

func (n *node) env() []string {
	return append(os.Environ(), "UNIC_HOME="+n.home, "UNIC_SOCK="+n.sock,
		"UNIC_MOCK_CLIPBOARD_DIR="+filepath.Join(n.home, "board"), "UNIC_RENDEZVOUS_URL=http://127.0.0.1:1")
}

func setup(env *testscript.Env) error {
	st := &state{work: env.WorkDir, nodes: map[string]*node{}}
	env.Values["state"] = st
	env.Defer(func() {
		st.mu.Lock()
		defer st.mu.Unlock()
		for _, n := range st.nodes {
			if dest := os.Getenv("UNIC_E2E_ARTIFACTS"); dest != "" {
				if out, _, err := n.unic("cache", "--json"); err == nil {
					dir := filepath.Join(dest, filepath.Base(env.WorkDir))
					_ = os.MkdirAll(dir, 0700)
					_ = os.WriteFile(filepath.Join(dir, n.name+".cache.json"), []byte(out), 0600)
				}
			}
			n.kill(syscall.SIGKILL)
			if n.done != nil {
				select {
				case <-n.done:
				case <-time.After(5 * time.Second):
				}
			}
		}
		for name := range st.nodes {
			if data, err := os.ReadFile(filepath.Join(st.work, name+".log")); err == nil && bytes.Contains(data, []byte("WARNING: DATA RACE")) {
				env.T().Fatal("daemon race detector reported a data race")
			}
		}
		exportArtifact(env, st)
	})
	return nil
}

func (n *node) kill(sig syscall.Signal) {
	if n.cmd != nil && n.cmd.Process != nil {
		_ = n.cmd.Process.Signal(sig)
	}
}

func stateOf(ts *testscript.TestScript) *state { return ts.Value("state").(*state) }

func (s *state) node(ts *testscript.TestScript, name string) *node {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := s.nodes[name]
	if n == nil {
		ts.Fatalf("unknown node %q (start it with node-start)", name)
	}
	return n
}

// unic runs the CLI as node n and returns its output.
func (n *node) unic(args ...string) (stdout, stderr string, err error) {
	cmd := exec.Command(filepath.Join(binDir, "unic"), args...)
	cmd.Env = n.env()
	var o, e bytes.Buffer
	cmd.Stdout, cmd.Stderr = &o, &e
	err = cmd.Run()
	return o.String(), e.String(), err
}

func commands() map[string]func(*testscript.TestScript, bool, []string) {
	return map[string]func(*testscript.TestScript, bool, []string){
		"node-start": cmdNodeStart,
		"node-stop":  cmdNodeStop,
		"u":          cmdU,
		"until":      cmdWait,
		"pair":       cmdPair,
		"genfile":    cmdGenfile,
		"sleep": func(ts *testscript.TestScript, _ bool, a []string) {
			d, err := time.ParseDuration(a[0])
			ts.Check(err)
			time.Sleep(d)
		},
		"logs":            cmdLogs,
		"retry-copy":      cmdRetryCopy,
		"node-id":         cmdNodeID,
		"external-ref":    cmdExternalRef,
		"file-path":       cmdFilePath,
		"history-age":     cmdHistoryAge,
		"cache-link":      cmdCacheLink,
		"config-conflict": cmdConfigConflict,
		"file-wait":       cmdFileWait,
		"board-set":       cmdBoardSet,
		"board-wait":      cmdBoardWait,
		"install-plugin":  cmdInstallPlugin,
	}
}

// node-start <name>: start a unicd with its own state directory (taken from
// <name>/ in the case's files, so config.toml and plugins can be preloaded)
// and an empty directory-backed clipboard, and wait for its socket.
// Starting a stopped node again keeps its state: that is a restart.
func cmdNodeStart(ts *testscript.TestScript, neg bool, args []string) {
	if len(args) != 1 {
		ts.Fatalf("usage: node-start name")
	}
	st := stateOf(ts)
	st.mu.Lock()
	n := st.nodes[args[0]]
	if n == nil {
		n = &node{name: args[0], home: filepath.Join(st.work, args[0])}
		n.sock = filepath.Join(st.work, "."+args[0]+".sock")
		st.nodes[args[0]] = n
	}
	st.mu.Unlock()
	if n.done != nil {
		select {
		case <-n.done:
		default:
			// The node is running: this starts a second daemon on the same
			// state directory, which must refuse (use `! node-start`).
			second := exec.Command(filepath.Join(binDir, "unicd"))
			logf, err := os.OpenFile(filepath.Join(st.work, args[0]+".log"), os.O_APPEND|os.O_WRONLY, 0o600)
			ts.Check(err)
			second.Env, second.Stdout, second.Stderr = n.env(), logf, logf
			ts.Check(second.Start())
			exited := make(chan struct{})
			go func() { _ = second.Wait(); _ = logf.Close(); close(exited) }()
			select {
			case <-exited:
				if !neg {
					ts.Fatalf("a second daemon on node %s's data directory exited, as it should, but node-start was not negated", args[0])
				}
			case <-time.After(10 * time.Second):
				_ = second.Process.Kill()
				ts.Fatalf("a second daemon on node %s's data directory kept running", args[0])
			}
			return
		}
	}
	ts.Check(os.MkdirAll(filepath.Join(n.home, "board"), 0o700))
	logf, err := os.OpenFile(filepath.Join(st.work, args[0]+".log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	ts.Check(err)
	cmd := exec.Command(filepath.Join(binDir, "unicd"))
	cmd.Env, cmd.Stdout, cmd.Stderr = n.env(), logf, logf
	ts.Check(cmd.Start())
	done := make(chan struct{})
	go func() { _ = cmd.Wait(); _ = logf.Close(); close(done) }()
	n.cmd, n.done = cmd, done
	deadline := time.Now().Add(20 * time.Second)
	for time.Now().Before(deadline) {
		if _, _, err := n.unic("status"); err == nil {
			if neg {
				ts.Fatalf("node %s started but it should not have", args[0])
			}
			return
		}
		select {
		case <-done:
			if neg {
				return // the daemon refused to start, as expected
			}
			ts.Fatalf("node %s exited at startup:\n%s", args[0], ts.ReadFile(args[0]+".log"))
		case <-time.After(100 * time.Millisecond):
		}
	}
	ts.Fatalf("node %s did not come up", args[0])
}

// node-stop <name> [TERM|KILL|STOP|CONT]: signal the daemon. TERM and KILL
// wait for it to exit; STOP and CONT do not.
func cmdNodeStop(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) < 1 || len(args) > 2 {
		ts.Fatalf("usage: node-stop name [TERM|KILL|STOP|CONT]")
	}
	n := stateOf(ts).node(ts, args[0])
	sig := "TERM"
	if len(args) == 2 {
		sig = args[1]
	}
	sigs := map[string]syscall.Signal{"TERM": syscall.SIGTERM, "KILL": syscall.SIGKILL, "STOP": syscall.SIGSTOP, "CONT": syscall.SIGCONT}
	s, ok := sigs[sig]
	if !ok {
		ts.Fatalf("unknown signal %q", sig)
	}
	n.kill(s)
	if sig == "TERM" || sig == "KILL" {
		select {
		case <-n.done:
		case <-time.After(15 * time.Second):
			ts.Fatalf("node %s did not exit after %s", args[0], sig)
		}
	}
}

// u <node> args...: run the unic CLI as that node. Its output is what the
// stdout/stderr assertions see; a nonzero exit fails unless negated (!).
func cmdU(ts *testscript.TestScript, neg bool, args []string) {
	if len(args) < 1 {
		ts.Fatalf("usage: u node args...")
	}
	n := stateOf(ts).node(ts, args[0])
	o, e, err := n.unic(args[1:]...)
	_, _ = ts.Stdout().Write([]byte(o))
	_, _ = ts.Stderr().Write([]byte(e))
	if neg && err == nil {
		ts.Fatalf("unic %s unexpectedly succeeded", strings.Join(args[1:], " "))
	}
	if !neg && err != nil {
		ts.Fatalf("unic %s: %v", strings.Join(args[1:], " "), err)
	}
}

// until <node> <regexp> args...: rerun `unic args` until its stdout matches,
// up to 40 seconds. With ! it instead requires that the output never matches
// for 3 seconds (an absence check that does not pass by being early).
func cmdWait(ts *testscript.TestScript, neg bool, args []string) {
	if len(args) < 3 {
		ts.Fatalf("usage: until node regexp args...")
	}
	n := stateOf(ts).node(ts, args[0])
	re, err := regexp.Compile("(?m)" + args[1])
	ts.Check(err)
	limit := 40 * time.Second
	if neg {
		limit = 3 * time.Second
	}
	deadline := time.Now().Add(limit)
	var last string
	for {
		o, _, _ := n.unic(args[2:]...)
		last = o
		if re.MatchString(o) {
			if neg {
				ts.Fatalf("`unic %s` matched /%s/ but must not:\n%s", strings.Join(args[2:], " "), args[1], o)
			}
			_, _ = ts.Stdout().Write([]byte(o))
			return
		}
		if time.Now().After(deadline) {
			break
		}
		time.Sleep(250 * time.Millisecond)
	}
	if !neg {
		ts.Fatalf("`unic %s` never matched /%s/; last output:\n%s", strings.Join(args[2:], " "), args[1], last)
	}
}

func pendingFingerprint(ts *testscript.TestScript, n *node) string {
	out, _, err := n.unic("requests")
	ts.Check(err)
	fp := regexp.MustCompile(`[0-9A-F]{4}(?: [0-9A-F]{4}){7}`).FindString(out)
	if fp == "" {
		ts.Fatalf("no fingerprint in requests: %s", out)
	}
	return fp
}

// pair <a> <b> [request|approve]: b pairs with a's full address (request),
// then both users approve after the fingerprints are compared equal
// (approve), and both sides see the other online. Without a stage, both run.
func cmdPair(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) < 2 || len(args) > 3 {
		ts.Fatalf("usage: pair a b [request|approve]")
	}
	stage := "both"
	if len(args) == 3 {
		stage = args[2]
	}
	st := stateOf(ts)
	a, b := st.node(ts, args[0]), st.node(ts, args[1])
	idOf := func(n *node) string {
		o, _, err := n.unic("status")
		ts.Check(err)
		m := regexp.MustCompile(`\(([a-z0-9]{26})\)`).FindStringSubmatch(o)
		if m == nil {
			ts.Fatalf("no device id in status:\n%s", o)
		}
		return m[1]
	}
	idA, idB := idOf(a), idOf(b)
	if stage == "request" || stage == "both" {
		addr, _, err := a.unic("addr")
		ts.Check(err)
		out, _, err := b.unic("pair", strings.TrimSpace(addr))
		ts.Check(err)
		fp := regexp.MustCompile(`(?m)^Fingerprint: ([0-9A-F ]+?)\s{2}`).FindStringSubmatch(out)
		if fp == nil {
			ts.Fatalf("no fingerprint in pair output:\n%s", out)
		}
		waitFor := func(n *node, id string) {
			deadline := time.Now().Add(30 * time.Second)
			for time.Now().Before(deadline) {
				o, _, _ := n.unic("requests")
				if strings.Contains(o, id) {
					if !strings.Contains(o, fp[1]) {
						ts.Fatalf("fingerprint on %s differs from %q:\n%s", n.name, fp[1], o)
					}
					return
				}
				time.Sleep(250 * time.Millisecond)
			}
			ts.Fatalf("%s never saw a request from %s", n.name, id)
		}
		waitFor(a, idB)
		waitFor(b, idA)
	}
	if stage == "approve" || stage == "both" {
		fpA, fpB := pendingFingerprint(ts, a), pendingFingerprint(ts, b)
		if _, _, err := a.unic("approve", idB); err == nil {
			ts.Fatalf("approval without fingerprint succeeded")
		}
		if _, _, err := a.unic("approve", idB, "0000 0000 0000 0000 0000 0000 0000 0000"); err == nil {
			ts.Fatalf("approval with wrong fingerprint succeeded")
		}
		_, _, err := a.unic("approve", idB, fpB)
		ts.Check(err)
		_, _, err = b.unic("approve", idA, fpA)
		ts.Check(err)
		for _, p := range [][2]string{{a.name, idB}, {b.name, idA}} {
			cmdWait(ts, false, []string{p[0], p[1] + `\s+\S+\s+online`, "peers"})
		}
	}
}

// genfile text|png|rand <path> [bytes]: create a file the case can compare
// with. rand is deterministic, so a failure reproduces.
func cmdGenfile(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) < 2 {
		ts.Fatalf("usage: genfile png|rand path [bytes]")
	}
	path := ts.MkAbs(args[1])
	switch args[0] {
	case "png":
		ts.Check(os.WriteFile(path, makePNG(), 0o600))
	case "rand":
		n := 1000
		if len(args) > 2 {
			v, err := strconv.Atoi(args[2])
			ts.Check(err)
			n = v
		}
		b := make([]byte, n)
		rand.New(rand.NewSource(int64(n))).Read(b)
		ts.Check(os.WriteFile(path, b, 0o600))
	default:
		ts.Fatalf("unknown kind %q", args[0])
	}
}

func makePNG() []byte {
	const w, h = 16, 16
	var raw bytes.Buffer
	for i := 0; i < h; i++ {
		raw.WriteByte(0)
		for j := 0; j < w; j++ {
			raw.Write([]byte{byte(i * 16), byte(j * 16), 128, 255})
		}
	}
	var z bytes.Buffer
	zw := zlib.NewWriter(&z)
	_, _ = zw.Write(raw.Bytes())
	_ = zw.Close()
	chunk := func(t string, d []byte) []byte {
		var b bytes.Buffer
		_ = binary.Write(&b, binary.BigEndian, uint32(len(d)))
		b.WriteString(t)
		b.Write(d)
		_ = binary.Write(&b, binary.BigEndian, crc32.ChecksumIEEE(append([]byte(t), d...)))
		return b.Bytes()
	}
	ihdr := new(bytes.Buffer)
	_ = binary.Write(ihdr, binary.BigEndian, [2]uint32{w, h})
	ihdr.Write([]byte{8, 6, 0, 0, 0})
	out := []byte("\x89PNG\r\n\x1a\n")
	out = append(out, chunk("IHDR", ihdr.Bytes())...)
	out = append(out, chunk("IDAT", z.Bytes())...)
	return append(out, chunk("IEND", nil)...)
}

// logs <node> <string>: the node's log must (or with ! must not) contain the
// string. Used to prove secrets never reach the logs.
func cmdLogs(ts *testscript.TestScript, neg bool, args []string) {
	if len(args) != 2 {
		ts.Fatalf("usage: logs node substring")
	}
	has := strings.Contains(ts.ReadFile(args[0]+".log"), args[1])
	if has == neg {
		ts.Fatalf("log of %s: contains %q = %v, wanted %v", args[0], args[1], has, !neg)
	}
}

// node-id <node> <VAR>: put the node's device id into $VAR.
func cmdNodeID(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) != 2 {
		ts.Fatalf("usage: node-id node VAR")
	}
	o, _, err := stateOf(ts).node(ts, args[0]).unic("status")
	ts.Check(err)
	m := regexp.MustCompile(`\(([a-z0-9]{26})\)`).FindStringSubmatch(o)
	if m == nil {
		ts.Fatalf("no device id in status:\n%s", o)
	}
	ts.Setenv(args[1], m[1])
}

var boardFile = map[string]string{"text": "text", "html": "html", "png": "png", "files": "files"}

// board-set <node> kind path [kind path ...]: change that node's clipboard
// the way an application would; kinds are text, html, png and files and
// several may be set at once (one copy with several representations). For
// files, <path> is the file to put on the clipboard; otherwise it is a file
// holding the content. The previous clipboard is replaced entirely.
func cmdBoardSet(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) < 3 || len(args)%2 != 1 {
		ts.Fatalf("usage: board-set node kind path [kind path ...]")
	}
	n := stateOf(ts).node(ts, args[0])
	dir := filepath.Join(n.home, "board")
	pairs := args[1:]
	for i := 0; i < len(pairs); i += 2 {
		if boardFile[pairs[i]] == "" {
			ts.Fatalf("unknown clipboard kind %q", pairs[i])
		}
	}
	for _, f := range boardFile {
		_ = os.Remove(filepath.Join(dir, f))
	}
	for i := 0; i < len(pairs); i += 2 {
		kind, src := pairs[i], pairs[i+1]
		data := []byte(ts.MkAbs(src) + "\n")
		if kind != "files" {
			data = []byte(ts.ReadFile(src))
		}
		tmp := filepath.Join(dir, ".tmp")
		ts.Check(os.WriteFile(tmp, data, 0o600))
		ts.Check(os.Rename(tmp, filepath.Join(dir, boardFile[kind])))
	}
}

// board-wait <node> kind path: wait up to 40 seconds until that node's
// clipboard holds exactly the content of <path>. For files the clipboard must
// list one file whose bytes equal <path>'s. With ! it requires the clipboard
// to stay different for 3 seconds.
func cmdBoardWait(ts *testscript.TestScript, neg bool, args []string) {
	if len(args) != 3 || boardFile[args[1]] == "" {
		ts.Fatalf("usage: board-wait node text|html|png|files path")
	}
	n := stateOf(ts).node(ts, args[0])
	want := ts.ReadFile(args[2])
	limit := 40 * time.Second
	if neg {
		limit = 3 * time.Second
	}
	read := func() []byte {
		b, _ := os.ReadFile(filepath.Join(n.home, "board", boardFile[args[1]]))
		if args[1] == "files" {
			list := strings.Fields(string(b))
			if len(list) != 1 {
				return nil
			}
			b, _ = os.ReadFile(list[0])
		}
		return b
	}
	deadline := time.Now().Add(limit)
	var got []byte
	for {
		got = read()
		if got != nil && string(got) == want {
			if neg {
				ts.Fatalf("clipboard of %s holds %s content that must not have arrived", args[0], args[1])
			}
			return
		}
		if time.Now().After(deadline) {
			break
		}
		time.Sleep(200 * time.Millisecond)
	}
	if !neg {
		ts.Fatalf("clipboard of %s never got the expected %s (%d bytes wanted, %d present)", args[0], args[1], len(want), len(got))
	}
}

// install-plugin <node> <name>: copy plugins/examples/lua/<name> into the
// node's local Lua plugin directory, as a user would after a git clone.
func cmdInstallPlugin(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) != 2 {
		ts.Fatalf("usage: install-plugin node name")
	}
	n := stateOf(ts).node(ts, args[0])
	root, err := repoRoot()
	ts.Check(err)
	dst := filepath.Join(n.home, "plugins", "lua", args[1])
	ts.Check(os.MkdirAll(dst, 0o700))
	src := filepath.Join(root, "plugins", "examples", "lua", args[1])
	ents, err := os.ReadDir(src)
	ts.Check(err)
	for _, e := range ents {
		b, err := os.ReadFile(filepath.Join(src, e.Name()))
		ts.Check(err)
		ts.Check(os.WriteFile(filepath.Join(dst, e.Name()), b, 0o600))
	}
}

// retry-copy <from> <to> <prefix>: copy "<prefix> <n>" on <from> every 5
// seconds until <to>'s clipboard shows a text with that prefix (up to 90
// seconds). A copy made while the peer's old connection is still believed up
// is lost (nothing is queued), so after a crash the first attempts may not
// arrive; this proves the link comes back, and logs how many tries it took.
func cmdRetryCopy(ts *testscript.TestScript, _ bool, args []string) {
	if len(args) != 3 {
		ts.Fatalf("usage: retry-copy from to prefix")
	}
	st := stateOf(ts)
	from, to := st.node(ts, args[0]), st.node(ts, args[1])
	deadline := time.Now().Add(90 * time.Second)
	for try := 1; time.Now().Before(deadline); try++ {
		_, _, err := from.unic("copy", fmt.Sprintf("%s %d", args[2], try))
		ts.Check(err)
		until := time.Now().Add(5 * time.Second)
		for time.Now().Before(until) {
			b, _ := os.ReadFile(filepath.Join(to.home, "board", "text"))
			if strings.HasPrefix(string(b), args[2]+" ") {
				ts.Logf("%s reached %s on attempt %d\n", args[0], args[1], try)
				return
			}
			time.Sleep(200 * time.Millisecond)
		}
	}
	ts.Fatalf("%s never reached %s", args[0], args[1])
}
